// src/routes/verify-email.jsx
import React, { useEffect, useState } from 'react';
import { useNavigate, useLocation, Link } from 'react-router-dom';
import { Logo } from '../components/logo';
import { Button } from '../components/ui/button';
import api from '../services/api';

export default function VerifyEmail() {
  const navigate = useNavigate();
  const location = useLocation();
  const [status, setStatus] = useState('verifying'); // 'verifying', 'success', 'error'
  const [message, setMessage] = useState('');

  useEffect(() => {
    const params = new URLSearchParams(location.search);
    const token = params.get('token');

    if (!token) {
      setStatus('error');
      setMessage('No verification token provided.');
      return;
    }

    // Verify email
    const verifyEmail = async () => {
      try {
        const response = await api.post('/auth/verify-email', { token });
        setStatus('success');
        setMessage(response.data.message);
        
        // Redirect to login after 3 seconds
        setTimeout(() => {
          navigate('/login');
        }, 3000);
      } catch (err) {
        setStatus('error');
        setMessage(err.response?.data?.message || 'Email verification failed. Please try again.');
      }
    };

    verifyEmail();
  }, [location, navigate]);

  if (status === 'verifying') {
    return (
      <div className="min-h-screen flex items-center justify-center p-6">
        <div className="text-center">
          <Logo className="justify-center" />
          <div className="mt-8">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-emerald mx-auto"></div>
            <h2 className="mt-4 text-lg font-semibold">Verifying your email...</h2>
            <p className="text-muted-foreground">Please wait while we verify your email address.</p>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex items-center justify-center p-6">
      <div className="text-center max-w-md">
        <Logo className="justify-center" />
        <div className="mt-8">
          {status === 'success' ? (
            <>
              <div className="w-16 h-16 bg-emerald/10 rounded-full flex items-center justify-center mx-auto">
                <svg className="w-8 h-8 text-emerald" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
                </svg>
              </div>
              <h2 className="mt-4 text-xl font-semibold text-foreground">Email Verified! ✅</h2>
              <p className="mt-2 text-muted-foreground">{message}</p>
              <p className="mt-1 text-sm text-muted-foreground">Redirecting to login page...</p>
            </>
          ) : (
            <>
              <div className="w-16 h-16 bg-red-500/10 rounded-full flex items-center justify-center mx-auto">
                <svg className="w-8 h-8 text-red-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                </svg>
              </div>
              <h2 className="mt-4 text-xl font-semibold text-foreground">Verification Failed</h2>
              <p className="mt-2 text-red-500">{message}</p>
            </>
          )}
          <div className="mt-6">
            <Link to="/login">
              <Button className="w-full rounded-lg bg-emerald text-primary-foreground shadow-glow hover:bg-emerald/90">
                Go to Login
              </Button>
            </Link>
          </div>
        </div>
      </div>
    </div>
  );
}
